BEGIN;
CREATE SCHEMA aurea_manager_rpc;
REVOKE ALL ON SCHEMA aurea_manager_rpc FROM PUBLIC,anon,authenticated,service_role;
GRANT USAGE ON SCHEMA aurea_manager_rpc TO authenticated;
ALTER FUNCTION public.aurea_manager_actions(p_organization_id uuid) SET SCHEMA aurea_manager_rpc;
REVOKE ALL ON FUNCTION aurea_manager_rpc.aurea_manager_actions(p_organization_id uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION aurea_manager_rpc.aurea_manager_actions(p_organization_id uuid) TO authenticated;
CREATE FUNCTION public.aurea_manager_actions(p_organization_id uuid) RETURNS TABLE(id uuid, cycle_id uuid, description text, due_on date, status text, created_at timestamp with time zone) LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM aurea_manager_rpc.aurea_manager_actions($1) $$;
REVOKE ALL ON FUNCTION public.aurea_manager_actions(p_organization_id uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.aurea_manager_actions(p_organization_id uuid) TO authenticated;
ALTER FUNCTION public.aurea_manager_cycles(p_organization_id uuid) SET SCHEMA aurea_manager_rpc;
REVOKE ALL ON FUNCTION aurea_manager_rpc.aurea_manager_cycles(p_organization_id uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION aurea_manager_rpc.aurea_manager_cycles(p_organization_id uuid) TO authenticated;
CREATE FUNCTION public.aurea_manager_cycles(p_organization_id uuid) RETURNS TABLE(cycle_id uuid, week_start date, state text) LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM aurea_manager_rpc.aurea_manager_cycles($1) $$;
REVOKE ALL ON FUNCTION public.aurea_manager_cycles(p_organization_id uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.aurea_manager_cycles(p_organization_id uuid) TO authenticated;
ALTER FUNCTION public.aurea_manager_save_action(p_organization_id uuid, p_description text, p_due_on date, p_cycle_id uuid, p_action_id uuid, p_status text) SET SCHEMA aurea_manager_rpc;
REVOKE ALL ON FUNCTION aurea_manager_rpc.aurea_manager_save_action(p_organization_id uuid, p_description text, p_due_on date, p_cycle_id uuid, p_action_id uuid, p_status text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION aurea_manager_rpc.aurea_manager_save_action(p_organization_id uuid, p_description text, p_due_on date, p_cycle_id uuid, p_action_id uuid, p_status text) TO authenticated;
CREATE FUNCTION public.aurea_manager_save_action(p_organization_id uuid, p_description text, p_due_on date DEFAULT NULL::date, p_cycle_id uuid DEFAULT NULL::uuid, p_action_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'open'::text) RETURNS uuid LANGUAGE sql  SECURITY INVOKER SET search_path='' AS $$ SELECT aurea_manager_rpc.aurea_manager_save_action($1,$2,$3,$4,$5,$6) $$;
REVOKE ALL ON FUNCTION public.aurea_manager_save_action(p_organization_id uuid, p_description text, p_due_on date, p_cycle_id uuid, p_action_id uuid, p_status text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.aurea_manager_save_action(p_organization_id uuid, p_description text, p_due_on date, p_cycle_id uuid, p_action_id uuid, p_status text) TO authenticated;
ALTER FUNCTION public.aurea_manager_summary(p_organization_id uuid) SET SCHEMA aurea_manager_rpc;
REVOKE ALL ON FUNCTION aurea_manager_rpc.aurea_manager_summary(p_organization_id uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION aurea_manager_rpc.aurea_manager_summary(p_organization_id uuid) TO authenticated;
CREATE FUNCTION public.aurea_manager_summary(p_organization_id uuid) RETURNS TABLE(week_start date, question_code text, domain text, response_count bigint, favorable_percent numeric) LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM aurea_manager_rpc.aurea_manager_summary($1) $$;
REVOKE ALL ON FUNCTION public.aurea_manager_summary(p_organization_id uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.aurea_manager_summary(p_organization_id uuid) TO authenticated;
ALTER FUNCTION public.aurea_my_companies() SET SCHEMA aurea_manager_rpc;
REVOKE ALL ON FUNCTION aurea_manager_rpc.aurea_my_companies() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION aurea_manager_rpc.aurea_my_companies() TO authenticated;
CREATE FUNCTION public.aurea_my_companies() RETURNS TABLE(organization_id uuid, organization_name text, member_role text) LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM aurea_manager_rpc.aurea_my_companies() $$;
REVOKE ALL ON FUNCTION public.aurea_my_companies() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.aurea_my_companies() TO authenticated;
REVOKE EXECUTE ON FUNCTION public.aurea_employee_invitation(text),public.aurea_employee_submit(text,jsonb) FROM service_role,aurea_employee_login;
COMMIT;
